/// Pad a component name into the fixed-size HornTag component field.
pub const fn horn_tag_component(bytes: &[u8]) -> [u8; 32] {
    let mut out = [0u8; 32];
    let mut index = 0;
    while index < bytes.len() && index < out.len() {
        out[index] = bytes[index];
        index += 1;
    }
    out
}

