        #[unsafe(link_section = ".horn")]
        pub static HORN_TAG: HornTag = HornTag {
            magic: *b"HORN",
            version: 1,
            component: $crate::horn_tag_component($component.as_bytes()),
            layout_hash: $layout_hash,
        };
