macro_rules! scalar_wire {
    ($ty:ty, $size:expr, $align:expr, $put:ident, $get:ident) => {
        impl Wire for $ty {
            const SIZE: usize = $size;
            const ALIGN: usize = $align;
            const CAPS: usize = 0;
            fn encode(&self, out: &mut Encoder<'_>) { out.$put(*self); }
            fn decode(input: &mut Decoder<'_>) -> Result<Self, RpcError> { input.$get() }
            fn caps(&self, _out: &mut dyn CapSink) -> Result<(), RpcError> { Ok(()) }
        }
    };
}

