    const ALIGN: usize = 8;
    const CAPS: usize = T::CAPS;
    fn encode(&self, out: &mut Encoder<'_>) {
        out.u64(if self.is_some() { 1 } else { 0 });
        out.align(T::ALIGN);
        match self {
            Some(value) => value.encode(out),
            None => T::default().encode(out),
        }
    }
    fn decode(input: &mut Decoder<'_>) -> Result<Self, RpcError> {
        let present = input.u64()?;
        input.align(T::ALIGN);
        let value = T::decode(input)?;
        Ok(if present != 0 { Some(value) } else { None })
    }
    fn caps(&self, out: &mut dyn CapSink) -> Result<(), RpcError> {
        if let Some(value) = self { value.caps(out)?; }
        Ok(())
    }
