#[repr(C)]
pub struct RingHeader {
    pub head: AtomicU32,
    pub tail: AtomicU32,
    pub capacity: u32,
    pub reserved: u32,
}

#[repr(C)]
pub struct Ring<T: Copy, const N: usize> {
    pub header: RingHeader,
    pub data: UnsafeCell<[T; N]>,
}

unsafe impl<T: Copy + Send, const N: usize> Sync for Ring<T, N> {}

impl<T: Copy, const N: usize> Ring<T, N> {
    pub fn init(&mut self) {
        self.header.head.store(0, Ordering::Relaxed);
        self.header.tail.store(0, Ordering::Relaxed);
        self.header.capacity = N as u32;
        self.header.reserved = 0;
    }
    pub fn push(&self, value: T) -> bool {
        let tail = self.header.tail.load(Ordering::Relaxed);
        let head = self.header.head.load(Ordering::Acquire);
        if tail.wrapping_sub(head) as usize >= N { return false; }
        unsafe {
            core::ptr::write((*self.data.get()).as_mut_ptr().add((tail as usize) % N), value);
        }
        self.header.tail.store(tail.wrapping_add(1), Ordering::Release);
        true
    }
    pub fn pop(&self) -> Option<T> {
        let head = self.header.head.load(Ordering::Relaxed);
        let tail = self.header.tail.load(Ordering::Acquire);
        if head == tail { return None; }
        let value = unsafe { core::ptr::read((*self.data.get()).as_ptr().add((head as usize) % N)) };
        self.header.head.store(head.wrapping_add(1), Ordering::Release);
        Some(value)
    }
}

