#[cfg(feature = "sel4")]
pub use sel4_space::Sel4CapSpace;

pub trait Transport {
    fn call<A: Wire, R: Wire>(
        &mut self,
        target: CapRef,
        label: u64,
        args: &A,
        request_layout: &'static CapLayout,
        result_layout: &'static CapLayout,
    ) -> Result<R, RpcError>;
    fn send<A: Wire>(
        &mut self,
        target: CapRef,
        label: u64,
        args: &A,
        request_layout: &'static CapLayout,
    ) -> Result<(), RpcError>;
}

